import { InjectionToken } from '@angular/core';

/** The user's choice (spec 002, REQ-5.2). */
export type ThemeChoice = 'light' | 'dark' | 'system';

/** The theme actually applied (REQ-5.1). */
export type ActiveTheme = 'light' | 'dark';

export const THEME_CHOICES: readonly ThemeChoice[] = ['light', 'dark', 'system'];

/** Saved per device under this key (REQ-5.2). The old `theme` key is never read (REQ-5.5). */
export const UI_THEME_STORAGE_KEY = 'ui.theme';

/**
 * A theme descriptor, as generated by the theme compiler next to the theme CSS
 * (for example `olivierTheme` from `@shared/theme-olivier`).
 */
export interface UiTheme {
  readonly name: string;
  readonly accents: readonly string[];
  readonly defaultAccent: string | null;
}

export interface UiConfig<T extends UiTheme = UiTheme> {
  /** The theme whose CSS the app loads. */
  theme: T;
  /** One of the theme's accents; defaults to the theme's own default accent. */
  accent?: T['accents'][number];
}

export const UI_CONFIG = new InjectionToken<UiConfig>('UI_CONFIG');

export function isThemeChoice(value: unknown): value is ThemeChoice {
  return typeof value === 'string' && (THEME_CHOICES as readonly string[]).includes(value);
}
